-- =============================================================================
-- 462 — LE CAHIER D'EXERCICES DE 3E (partie 6)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 462 --niveau 3e --fichiers svt.m3,emc.m1 --suffixe 6 > supabase/contenu/462_exercices_3e_6.sql
--
-- 57 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   emc.m1                  30 exercices · 10 chapitres
--   svt.m3                  27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('dcaa1027-5f64-57e5-8fb6-111ee36563f1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que dit la loi","competence":"analyser-texte","situation":"Le professeur d’EMC distribue un extrait de loi adapté pour la classe. Il s’agit de repérer ce qui définit une discrimination.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"Définition de la discrimination","blocs":["La discrimination est une différence de traitement défavorable, fondée sur un critère interdit par la loi, comme l’origine, le sexe ou le handicap.","Elle est punie de trois ans d’emprisonnement et de 45 000 € d’amende."],"source":"D’après le Code pénal, articles 225-1 et 225-2 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois critères interdits cités dans le texte.","aide":"Ils suivent l’expression « comme l’ ».","type":"zone","document":"loi","multiple":true},{"enonce":"Pendant combien d’années de prison une discrimination est-elle punie au maximum ?","aide":"Lis la dernière phrase du texte.","type":"nombre","unite":"ans"},{"enonce":"Laquelle de ces situations est une discrimination ?","aide":"Il faut un traitement défavorable, un critère interdit et un domaine protégé.","type":"choix","options":[{"id":"a","texte":"Choisir un ami selon ses goûts"},{"id":"b","texte":"Refuser un emploi à un candidat sans le diplôme exigé"},{"id":"c","texte":"Refuser de louer un logement à quelqu’un à cause de son nom"},{"id":"d","texte":"Ne pas inviter quelqu’un à son anniversaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m20","m23"]},"explication":"**Origine**, **sexe** et **handicap** font partie des critères interdits, avec la religion, l’âge ou l’apparence physique."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 ans","explication":"Jusqu’à **3 ans d’emprisonnement** et **45 000 €** d’amende pour un particulier ou une entreprise."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **nom** renvoie à l’origine, critère interdit ; le **logement** est un domaine protégé. Le diplôme, lui, est un critère **pertinent**."}]$ex$::jsonb),
  ('dcaa1027-5f64-57e5-8fb6-111ee36563f1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Directe, indirecte ou légitime ?","competence":"analyser-document","situation":"Une conseillère de la mission locale présente à des lycéens plusieurs cas tirés de situations réelles. Il faut les classer.","documents":[{"id":"cas","type":"tableau","titre":"Quatre situations","colonnes":["N°","La situation"],"lignes":[["1","Une entreprise écarte un candidat qui n’a pas le diplôme exigé pour le poste."],["2","Un propriétaire refuse de louer à une famille à cause de son nom."],["3","Un employeur refuse un candidat sans permis alors que le poste demande de conduire."],["4","Un club refuse une joueuse à cause de son handicap, alors que l’activité peut être adaptée."]],"enteteLignes":true,"source":"Cas imaginés pour l’exercice."},{"id":"reglement","type":"texte","genre":"consigne","titre":"Un règlement de recrutement","blocs":["« Pour devenir agent d’accueil, il faut mesurer au moins 1,80 m. » Cette taille n’a aucun lien avec les missions du poste, mais elle écarte surtout des femmes."],"source":"Règlement imaginé pour l’exercice."}],"questions":[{"enonce":"Classe chaque situation du tableau.","aide":"Un critère pertinent pour le poste est légitime ; un critère interdit non.","type":"categories","categories":[{"id":"c0","texte":"Discrimination"},{"id":"c1","texte":"Différence légitime"}],"items":[{"id":"i0","texte":"Situation 1"},{"id":"i1","texte":"Situation 4"},{"id":"i2","texte":"Situation 2"},{"id":"i3","texte":"Situation 3"}]},{"enonce":"Le règlement sur la taille minimale est une discrimination…","aide":"La règle est neutre en apparence, mais défavorise un groupe.","type":"choix","options":[{"id":"a","texte":"Inexistante"},{"id":"b","texte":"Légitime"},{"id":"c","texte":"Indirecte"},{"id":"d","texte":"Directe"}],"multiple":false},{"enonce":"Le recruteur dit : « Je n’ai pas voulu discriminer, ça m’est venu naturellement. » Est-ce une défense valable ?","aide":"Le droit juge le résultat de l’acte.","type":"choix","options":[{"id":"a","texte":"Oui, si c’est la première fois"},{"id":"b","texte":"Oui : sans intention, pas de délit"},{"id":"c","texte":"Non : le droit regarde ce qui a été fait, pas l’intention"},{"id":"d","texte":"Non, sauf s’il a des excuses écrites"}],"multiple":false},{"enonce":"Quelle autorité indépendante peut être saisie gratuitement par toute personne qui s’estime discriminée ?","aide":"Son nom commence par « Défenseur ».","type":"texte","placeholder":"Nom de l’autorité"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Les situations **1** et **3** reposent sur un critère **pertinent** (diplôme, permis). Les situations **2** (nom) et **4** (handicap) reposent sur un critère **interdit**."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est une discrimination **indirecte** : une règle neutre en apparence qui défavorise en fait un groupe (ici les femmes)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le droit ne demande pas ce que la personne a **voulu** faire, mais ce qu’elle a **fait** : on peut discriminer sans se penser raciste ou sexiste."},{"cle":{"type":"texte","acceptes":["defenseur des droits","le defenseur des droits"]},"affichage":"défenseur des droits","explication":"C’est le **Défenseur des droits**, saisi gratuitement par toute personne."}]$ex$::jsonb),
  ('dcaa1027-5f64-57e5-8fb6-111ee36563f1'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le test des deux candidatures","competence":"argumenter","situation":"Une association envoie 100 candidatures identiques, à une seule différence près : le nom sur le CV. Elle compare les réponses positives. La responsable des ressources humaines répond par courrier, écrit pour l’exercice.","documents":[{"id":"testing","type":"graphique","forme":"barres","titre":"Réponses positives sur 100 candidatures","categories":["Candidature A","Candidature B"],"series":[{"nom":"Réponses positives","valeurs":[42,21],"teinte":"violet"}],"axeY":{"titre":"Réponses positives","unite":"sur 100","min":0,"max":50,"pas":10},"valeurs":false,"source":"Résultats imaginés pour l’exercice."},{"id":"courrier","type":"texte","genre":"lettre","titre":"Réponse de la direction","blocs":["Nous n’avons jamais eu l’intention de discriminer. Nous cherchions simplement un profil qui « corresponde à notre équipe »."],"source":"Courrier écrit pour l’exercice."}],"questions":[{"enonce":"Touche la candidature qui reçoit le moins de réponses positives.","aide":"Compare la hauteur des deux barres.","type":"zone","document":"testing","multiple":false},{"enonce":"Quel est l’écart de réponses positives entre les deux candidatures ?","aide":"Soustrais 21 à 42.","type":"nombre","unite":"réponses"},{"enonce":"À quoi sert le « testing » ?","aide":"Les deux CV sont identiques sauf sur un critère.","type":"choix","options":[{"id":"a","texte":"À choisir le meilleur candidat"},{"id":"b","texte":"À sanctionner l’association"},{"id":"c","texte":"À comparer deux candidatures identiques, sauf sur un critère, pour prouver une discrimination"},{"id":"d","texte":"À tester les compétences du candidat"}],"multiple":false},{"enonce":"La direction dit n’avoir « jamais eu l’intention » de discriminer. Peut-elle être condamnée ?","aide":"Relis la dernière phrase de la leçon sur les sanctions.","type":"choix","options":[{"id":"a","texte":"Oui, mais seulement si elle l’avoue"},{"id":"b","texte":"Non, car elle a écrit un courrier poli"},{"id":"c","texte":"Non : sans intention, aucune faute"},{"id":"d","texte":"Oui : l’intention n’est pas nécessaire, le résultat suffit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"La candidature **B** reçoit 21 réponses positives, deux fois moins que la A."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 réponses","explication":"42 − 21 = **21 réponses** d’écart. Les deux CV étant identiques, la différence vient du critère comparé."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **testing** compare deux candidatures identiques sauf sur un critère : c’est une preuve **admise en justice**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il n’est **pas nécessaire** d’avoir voulu discriminer : l’acte, lui, suffit pour qu’il y ait délit."}]$ex$::jsonb),
  ('b2c56dae-8863-5ab9-a39d-3e650eb92870'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le droit de dire","competence":"analyser-texte","situation":"L’article 11 de la Déclaration de 1789 est au cœur de la liberté d’expression. Lis cette version adaptée pour la classe.","documents":[{"id":"art11","type":"texte","genre":"source","titre":"Article 11 (adapté)","blocs":["La libre communication des pensées et des opinions est un droit très précieux. Chacun peut parler, écrire et publier librement, mais doit répondre des abus de cette liberté dans les cas fixés par la loi."],"source":"D’après l’article 11 de la Déclaration des droits de l’homme et du citoyen de 1789 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois verbes qui disent ce que chacun peut faire librement.","aide":"Ils sont dans la deuxième phrase, après « Chacun peut ».","type":"zone","document":"art11","multiple":true},{"enonce":"Quelle loi du 29 juillet 1881 encadre la liberté de la presse et ses limites ?","aide":"Elle est citée dans la leçon avec la Déclaration de 1789.","type":"choix","options":[{"id":"a","texte":"La loi sur la laïcité"},{"id":"b","texte":"La loi sur le service civique"},{"id":"c","texte":"La loi sur la liberté de la presse"},{"id":"d","texte":"La loi sur le vote des femmes"}],"multiple":false},{"enonce":"Associe chaque délit à sa définition.","aide":"Pour l’une, il y a un fait précis ; pour l’autre, non.","type":"association","gauche":[{"id":"g0","texte":"Injure"},{"id":"g1","texte":"Diffamation"},{"id":"g2","texte":"Apologie du terrorisme"}],"droite":[{"id":"d0","texte":"La présentation favorable d’un acte terroriste"},{"id":"d1","texte":"Un fait faux qui porte atteinte à l’honneur"},{"id":"d2","texte":"Une expression outrageante, sans fait précis"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m16","m18"]},"explication":"Chacun peut **parler**, **écrire** et **publier** librement, tout en répondant des abus prévus par la loi."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **loi du 29 juillet 1881** pose la liberté de la presse **et** ses limites."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"L’**injure** est outrageante sans fait précis ; la **diffamation** allègue un fait **faux** ; l’**apologie du terrorisme** présente un acte sous un jour favorable."}]$ex$::jsonb),
  ('b2c56dae-8863-5ab9-a39d-3e650eb92870'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Sur le forum de la classe","competence":"argumenter","situation":"Noé et Lila discutent de ce qu’on peut écrire sur internet. Leur échange est écrit pour l’exercice.","documents":[{"id":"forum","type":"dialogue","modele":"bulles","titre":"Discussion à propos d’internet","participants":[{"nom":"Noé","emoji":"👦","cote":"gauche"},{"nom":"Lila","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Noé","texte":"Sur internet je peux tout écrire : avec mon pseudo, personne ne sait qui je suis."},{"qui":"Lila","texte":"Faux. Ton adresse IP permet de te retrouver, et la loi s’applique de la même façon en ligne."},{"qui":"Noé","texte":"Et si je ne fais que partager un message qui n’est pas de moi ?"},{"qui":"Lila","texte":"Partager, c’est diffuser : tu es concerné aussi."}],"source":"Dialogue écrit pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui exprime la fausse protection dont parle Noé.","aide":"Il pense qu’un faux nom suffit à ne pas être retrouvé.","type":"zone","document":"forum","multiple":false},{"enonce":"Qu’est-ce qui permet de retrouver l’auteur d’un message posté sous pseudonyme ?","aide":"Lila le dit dans sa première réponse.","type":"choix","options":[{"id":"a","texte":"L’adresse IP"},{"id":"b","texte":"Son nombre d’abonnés"},{"id":"c","texte":"Le prénom de ses amis"},{"id":"d","texte":"La couleur de l’écran"}],"multiple":false},{"enonce":"Partager un contenu illicite, est-ce engager sa responsabilité ?","aide":"Pense à la dernière réplique de Lila.","type":"choix","options":[{"id":"a","texte":"Non, sauf avec un pseudo"},{"id":"b","texte":"Oui, mais uniquement pour un adulte"},{"id":"c","texte":"Oui : publier, partager ou retweeter, c’est diffuser"},{"id":"d","texte":"Non : seul l’auteur est responsable"}],"multiple":false},{"enonce":"Trie ces propos : protégés ou punis par la loi ?","aide":"La frontière n’est pas entre le poli et l’impoli.","type":"categories","categories":[{"id":"c0","texte":"Protégé"},{"id":"c1","texte":"Puni"}],"items":[{"id":"i0","texte":"Insulter un camarade dans un commentaire"},{"id":"i1","texte":"Affirmer à tort qu’un camarade a volé"},{"id":"i2","texte":"Critiquer une religion ou une idée"},{"id":"i3","texte":"Appeler à s’en prendre à des personnes à cause de leur religion"},{"id":"i4","texte":"Se moquer d’un parti politique par une caricature"},{"id":"i5","texte":"Critiquer une loi"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"Le **pseudonyme** ne protège pas : le message est traçable par l’**adresse IP**."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’**adresse IP** du message permet de remonter jusqu’à son auteur."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Partager** un contenu illicite, c’est le **diffuser** : cela engage aussi celui qui partage."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"La frontière passe entre l’**idée** (qu’on peut critiquer) et la **personne** (qu’on ne peut pas viser par la haine, l’injure ou la diffamation)."}]$ex$::jsonb),
  ('b2c56dae-8863-5ab9-a39d-3e650eb92870'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une photo qui tourne","competence":"analyser-document","situation":"Dans le groupe de messagerie d’une classe, une photo circule. Chacun a un rôle dans ce qui s’est passé. Le récit est écrit pour l’exercice.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Dans le groupe de la 3e B","blocs":["Tom publie une photo de Yanis endormi en cours, sans lui demander son accord.","Clara écrit : « Yanis a volé le portable de Maëlle », alors que c’est faux.","Hugo ajoute : « T’es vraiment nul ». Enfin, Inès partage la photo à tout le collège."],"source":"Récit écrit pour l’exercice."},{"id":"qualif","type":"tableau","titre":"Qui a fait quoi ?","colonnes":["Auteur","Acte"],"lignes":[["Tom","Diffuse la photo sans l’accord de Yanis"],["Clara","Affirme un fait faux qui porte atteinte à l’honneur"],["Hugo","Écrit une expression outrageante, sans fait précis"],["Inès","Partage la photo à tout le collège"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice."}],"questions":[{"enonce":"Touche les deux mots qui montrent que Clara commet une diffamation.","aide":"Elle avance un fait, et il est inexact.","type":"zone","document":"recit","multiple":true},{"enonce":"Associe chaque auteur à la qualification de son acte.","aide":"Regarde ce que fait chacun dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"Tom"},{"id":"g1","texte":"Clara"},{"id":"g2","texte":"Hugo"},{"id":"g3","texte":"Inès"}],"droite":[{"id":"d0","texte":"Diffusion : celui qui partage est concerné"},{"id":"d1","texte":"Injure"},{"id":"d2","texte":"Diffamation"},{"id":"d3","texte":"Atteinte au droit à l’image"}]},{"enonce":"Où passe la frontière de la liberté d’expression dans cette histoire ?","aide":"On peut critiquer une idée, pas s’en prendre à une personne.","type":"choix","options":[{"id":"a","texte":"Entre les adultes et les élèves"},{"id":"b","texte":"Entre le poli et l’impoli"},{"id":"c","texte":"Entre l’idée et la personne"},{"id":"d","texte":"Entre internet et la vie réelle"}],"multiple":false},{"enonce":"Peut-on diffuser la photo de quelqu’un sans son accord, si elle n’est pas insultante ?","aide":"Relis l’encadré sur le droit à l’image.","type":"choix","options":[{"id":"a","texte":"Oui, si elle est drôle"},{"id":"b","texte":"Non : le droit à l’image protège aussi les images neutres"},{"id":"c","texte":"Oui, entre élèves de la même classe"},{"id":"d","texte":"Oui : une photo neutre n’est pas un problème"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m27"]},"explication":"Clara avance un fait précis (« volé ») qui est **faux** : c’est une **diffamation**."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"**Tom** viole le droit à l’image, **Clara** diffame, **Hugo** injurie et **Inès**, en partageant, **diffuse** à son tour."},{"cle":{"type":"choix","ids":["c"]},"explication":"La frontière est entre l’**idée** et la **personne**, pas entre le poli et l’impoli."},{"cle":{"type":"choix","ids":["b"]},"explication":"Diffuser une image **sans l’accord** de la personne est interdit, **même** si elle n’est pas insultante."}]$ex$::jsonb),
  ('c7e7d8da-139b-5834-99ef-74e2e7d5d907'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La journée numérique d’Ilan","competence":"analyser-document","situation":"Ilan, 14 ans, a laissé des traces numériques tout au long de sa journée. Certaines viennent de lui, d’autres non.","documents":[{"id":"journee","type":"tableau","titre":"Les traces d’Ilan","colonnes":["Heure","Ce qui se passe"],"lignes":[["8 h","Ilan publie une photo de son petit-déjeuner."],["12 h","Une amie le tague sur une photo de classe."],["15 h","Son application de sport enregistre sa position."],["20 h","Il tape des recherches sur un moteur de recherche."]],"enteteLignes":true,"source":"Journée imaginée pour l’exercice."}],"questions":[{"enonce":"Touche la ligne où une trace est laissée par quelqu’un d’autre qu’Ilan.","aide":"Cherche l’heure où une amie le tague.","type":"zone","document":"journee","multiple":false},{"enonce":"Classe chaque trace selon qui la produit.","aide":"Trois couches : publier, être publié, être enregistré.","type":"categories","categories":[{"id":"c0","texte":"Ce que je publie"},{"id":"c1","texte":"Ce que d’autres publient"},{"id":"c2","texte":"Ce que les services enregistrent"}],"items":[{"id":"i0","texte":"Ma position enregistrée par une appli"},{"id":"i1","texte":"Une amie qui me tague sur une photo"},{"id":"i2","texte":"Ma photo de profil"},{"id":"i3","texte":"Mes recherches sur un moteur"},{"id":"i4","texte":"Un article du journal du collège qui parle de moi"},{"id":"i5","texte":"Un commentaire que j’écris sous une vidéo"}]},{"enonce":"Quel article du Code civil protège la vie privée ?","aide":"Il protège le domicile, la santé, la vie sentimentale, les convictions et l’image.","type":"choix","options":[{"id":"a","texte":"L’article 11"},{"id":"b","texte":"L’article 9"},{"id":"c","texte":"L’article 225"},{"id":"d","texte":"L’article 1"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Quand une amie le tague, c’est un contenu publié par **d’autres** sur lui, sans qu’il l’ait choisi."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c2","i4":"c1","i5":"c0"}},"explication":"L’identité numérique a **trois couches** : ce qu’on publie, ce que d’autres publient sur nous, ce que les services **enregistrent** sans qu’on le voie."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’**article 9 du Code civil** protège la vie privée."}]$ex$::jsonb),
  ('c7e7d8da-139b-5834-99ef-74e2e7d5d907'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mélissa et l’application","competence":"analyser-document","situation":"Mélissa a 14 ans et veut s’inscrire sur une application. Son frère Hugo lui explique ce que dit la loi. La conversation est écrite pour l’exercice.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Conversation de Mélissa et de Hugo","participants":[{"nom":"Mélissa","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mélissa","texte":"L’appli demande mon accord pour utiliser mes données. J’ai 14 ans, je peux le donner seule ?"},{"qui":"Hugo","texte":"Non, avant l’âge du consentement autonome, il faut l’accord d’un parent."},{"qui":"Mélissa","texte":"Et si je veux ensuite voir ou effacer mes données ?"},{"qui":"Hugo","texte":"Le RGPD te donne des droits, et tu peux saisir la CNIL."}],"source":"Dialogue écrit pour l’exercice."},{"id":"droits","type":"tableau","titre":"Les droits du RGPD","colonnes":["Le droit","Ce qu’il permet"],"lignes":[["Accès","Savoir quelles données sont détenues"],["Rectification","?"],["Effacement","?"],["Opposition","?"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"À partir de quel âge peut-on consentir seul au traitement de ses données en France ?","aide":"Mélissa n’a pas encore cet âge.","type":"nombre","unite":"ans"},{"enonce":"Que doit faire Mélissa, qui a 14 ans, pour s’inscrire ?","aide":"Elle a moins de 15 ans.","type":"choix","options":[{"id":"a","texte":"Rien : l’appli est gratuite"},{"id":"b","texte":"Obtenir l’accord d’un parent"},{"id":"c","texte":"Attendre 18 ans"},{"id":"d","texte":"Mentir sur son âge"}],"multiple":false},{"enonce":"Associe chaque droit du RGPD à ce qu’il permet.","aide":"Le RGPD est entré en application en 2018.","type":"association","gauche":[{"id":"g0","texte":"Accès"},{"id":"g1","texte":"Rectification"},{"id":"g2","texte":"Effacement"},{"id":"g3","texte":"Opposition"}],"droite":[{"id":"d0","texte":"Refuser un usage de ses données"},{"id":"d1","texte":"Demander leur suppression"},{"id":"d2","texte":"Consulter ses données"},{"id":"d3","texte":"Les corriger"}]},{"enonce":"Quelle autorité française veille à la protection des données personnelles ?","aide":"Elle est citée dans la dernière réplique de Hugo.","type":"texte","placeholder":"Un sigle"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 ans","explication":"En France, on consent seul à **15 ans** ; en dessous, il faut l’accord d’un parent."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avant 15 ans, il faut l’**accord d’un parent** pour que le service traite ses données."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"**Accès** : consulter ; **rectification** : corriger ; **effacement** : le « droit à l’oubli » ; **opposition** : refuser un usage."},{"cle":{"type":"texte","acceptes":["cnil","la cnil"]},"affichage":"cnil","explication":"C’est la **CNIL**, qui peut être saisie en cas de problème."}]$ex$::jsonb),
