   $ex${"titre":"Supprimer ne suffit pas","competence":"argumenter","situation":"Une élève a publié une vidéo moqueuse à 13 ans, puis l’a supprimée. Trois ans plus tard, elle ressurgit. Le chemin de la vidéo est schématisé.","documents":[{"id":"chemin","type":"chaine","titre":"Le chemin d’une publication","disposition":"colonne","noeuds":[{"id":"z1","texte":"Je publie une vidéo"},{"id":"z2","texte":"Un contact en fait une capture"},{"id":"z3","texte":"La capture est partagée et archivée"},{"id":"z4","texte":"Je supprime ma publication"},{"id":"z5","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]},{"id":"temoin","type":"texte","genre":"lettre","titre":"Le témoignage de Camille","blocs":["J’ai supprimé ma vidéo depuis longtemps. Pourtant, quelqu’un l’a retrouvée et l’a montrée à un employeur potentiel pour mon stage."],"source":"Témoignage écrit pour l’exercice."}],"questions":[{"enonce":"Touche l’étape qui explique pourquoi supprimer sa publication ne suffit pas.","aide":"Quelqu’un d’autre en garde une trace.","type":"zone","document":"chemin","multiple":false},{"enonce":"Que devrait indiquer le dernier « ? » ?","aide":"Relis la ligne « permanence » de la leçon.","type":"choix","options":[{"id":"a","texte":"L’image a disparu pour toujours"},{"id":"b","texte":"L’image est désormais privée"},{"id":"c","texte":"L’image existe toujours ailleurs, copiée ou archivée"},{"id":"d","texte":"L’image est devenue légale"}],"multiple":false},{"enonce":"Trie ces réflexes : à adopter ou à éviter.","aide":"Pense à ce qui protège la vie privée, et à ce qui la menace.","type":"categories","categories":[{"id":"c0","texte":"À adopter"},{"id":"c1","texte":"À éviter"}],"items":[{"id":"i0","texte":"Diffuser une image intime"},{"id":"i1","texte":"Réfléchir avant de publier la photo d’un camarade"},{"id":"i2","texte":"Utiliser des mots de passe distincts"},{"id":"i3","texte":"Régler la confidentialité de ses comptes"},{"id":"i4","texte":"Poster sans réfléchir une photo de quelqu’un d’autre"}]},{"enonce":"Pourquoi une publication de collège peut-elle ressortir dix ans plus tard ?","aide":"Pense au chemin schématisé.","type":"choix","options":[{"id":"a","texte":"Parce que le contenu a pu être copié et archivé"},{"id":"b","texte":"Parce que la loi interdit de supprimer"},{"id":"c","texte":"Parce que seul l’auteur peut la retrouver"},{"id":"d","texte":"Parce qu’internet efface tout au bout de dix ans"}],"multiple":false}]}$ex$::jsonb,
