  ('4e512c0e-ff95-5285-96dc-155942cda412'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La loi de 1905","competence":"analyser-texte","situation":"La loi du 9 décembre 1905 est le texte fondateur de la laïcité. Voici ses deux idées, présentées dans un extrait adapté.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"La loi de séparation (adaptée)","blocs":["La République garantit la liberté de conscience et le libre exercice des cultes.","Elle ne reconnaît, ne salarie et ne subventionne aucun culte."],"source":"D’après la loi du 9 décembre 1905 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois verbes qui expriment le principe de séparation de l’État et des cultes.","aide":"Ils sont dans la deuxième phrase.","type":"zone","document":"loi","multiple":true},{"enonce":"Associe chaque pilier de la laïcité à ce qu’il garantit.","aide":"Chaque pilier a un mot-clé dans son nom.","type":"association","gauche":[{"id":"g0","texte":"Liberté de conscience"},{"id":"g1","texte":"Séparation"},{"id":"g2","texte":"Égalité"}],"droite":[{"id":"d0","texte":"L’État ne reconnaît ni ne finance aucun culte"},{"id":"d1","texte":"Croire, ne pas croire, changer, pratiquer ou non"},{"id":"d2","texte":"Tous égaux devant la loi, quelle que soit leur croyance"}]},{"enonce":"La laïcité, est-ce l’athéisme de l’État ?","aide":"Le texte garantit aussi le libre exercice des cultes.","type":"choix","options":[{"id":"a","texte":"Oui, mais seulement à l’école"},{"id":"b","texte":"Oui, depuis 1905"},{"id":"c","texte":"Oui : l’État est athée"},{"id":"d","texte":"Non : l’État n’a pas d’opinion sur Dieu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m17","m20"]},"explication":"L’État ne **reconnaît**, ne **salarie** et ne **subventionne** aucun culte : c’est la **séparation**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Trois piliers : **liberté de conscience**, **séparation**, **égalité**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La laïcité n’est **pas** l’athéisme d’État : l’État n’a pas d’opinion sur Dieu et garantit le libre exercice des cultes."}]$ex$::jsonb),
  ('4e512c0e-ff95-5285-96dc-155942cda412'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où s’applique la loi de 2004 ?","competence":"lire-tableau","situation":"La loi du 15 mars 2004 interdit les signes religieux ostensibles aux élèves, mais pas partout. Un tableau précise les lieux concernés.","documents":[{"id":"lieux","type":"tableau","titre":"La loi de 2004, lieu par lieu","colonnes":["Le lieu","La loi s’applique-t-elle ?"],"lignes":[["École, collège, lycée publics","Oui"],["Université","Non"],["La rue","Non"],["Établissement privé sous contrat","Non"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"Touche la case qui indique le seul lieu où la loi s’applique.","aide":"Cherche le « Oui ».","type":"zone","document":"lieux","multiple":false},{"enonce":"Sur les quatre lieux du tableau, dans combien la loi de 2004 ne s’applique-t-elle PAS ?","aide":"Compte les « Non ».","type":"nombre","unite":"lieux"},{"enonce":"Un enseignant d’un collège public peut-il manifester ses convictions religieuses en classe ?","aide":"La neutralité s’applique dans l’exercice des fonctions.","type":"choix","options":[{"id":"a","texte":"Oui, mais seulement le matin"},{"id":"b","texte":"Non, même dans sa vie privée"},{"id":"c","texte":"Non : les agents publics sont neutres dans l’exercice de leurs fonctions"},{"id":"d","texte":"Oui : c’est sa liberté d’expression"}],"multiple":false},{"enonce":"Quel régime particulier est toujours en vigueur en Alsace-Moselle ?","aide":"Ces régions étaient allemandes en 1905.","type":"texte","placeholder":"Un nom"}]}$ex$::jsonb,
