  ('4e512c0e-ff95-5285-96dc-155942cda412'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un débat sur la laïcité","competence":"argumenter","situation":"En classe, Sacha répète une idée entendue autour de lui. Maya la corrige. Le dialogue est écrit pour l’exercice.","documents":[{"id":"debat","type":"dialogue","modele":"bulles","titre":"Un débat en classe","participants":[{"nom":"Sacha","emoji":"👦","cote":"gauche"},{"nom":"Maya","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Sacha","texte":"Ma cousine dit que la laïcité, c’est interdire les religions."},{"qui":"Maya","texte":"Non : l’État est neutre, mais la loi de 1905 garantit aussi le libre exercice des cultes."},{"qui":"Sacha","texte":"Et en Alsace-Moselle, c’est pareil ?"},{"qui":"Maya","texte":"Pas tout à fait : ces régions étaient allemandes en 1905, le Concordat y est resté."}],"source":"Dialogue écrit pour l’exercice."},{"id":"neutralite","type":"tableau","titre":"Qui doit la neutralité ?","colonnes":["La personne","Son obligation"],"lignes":[["Agents publics (enseignants, policiers, employés de mairie)","?"],["Usagers d’un service public","Libres, sauf exception prévue par la loi"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui exprime l’idée fausse de Sacha.","aide":"C’est le verbe qui dit ce que la laïcité ne fait pas.","type":"zone","document":"debat","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » pour les agents publics ?","aide":"Regarde la situation des usagers, par contraste.","type":"choix","options":[{"id":"a","texte":"Libres de manifester leurs convictions en service"},{"id":"b","texte":"Neutres dans l’exercice de leurs fonctions, pas dans leur vie privée"},{"id":"c","texte":"Neutres partout, tout le temps"},{"id":"d","texte":"Aucune obligation"}],"multiple":false},{"enonce":"Pourquoi l’Alsace-Moselle a-t-elle gardé le Concordat ?","aide":"Maya donne la raison dans sa dernière réplique.","type":"choix","options":[{"id":"a","texte":"Parce qu’elle a refusé la loi"},{"id":"b","texte":"Parce que la loi de 1905 l’y autorise explicitement"},{"id":"c","texte":"Parce qu’elle est plus religieuse"},{"id":"d","texte":"Parce qu’elle était allemande en 1905"}],"multiple":false},{"enonce":"Trie ces affirmations : idée fausse ou idée juste sur la laïcité.","aide":"La loi de 1905 a deux faces.","type":"categories","categories":[{"id":"c0","texte":"Idée fausse"},{"id":"c1","texte":"Idée juste"}],"items":[{"id":"i0","texte":"Un usager d’un service public est libre, sauf exception prévue par la loi"},{"id":"i1","texte":"On ne peut porter aucun signe religieux dans la rue"},{"id":"i2","texte":"La laïcité protège chaque croyant, et l’incroyant de toutes les croyances"},{"id":"i3","texte":"L’État est athée"},{"id":"i4","texte":"L’État n’a pas d’opinion sur Dieu"},{"id":"i5","texte":"La loi de 1905 ne garantit que la neutralité de l’État"}]}]}$ex$::jsonb,
