r son juge"},{"id":"b","texte":"De ne pas être jugé"},{"id":"c","texte":"De supprimer une amende"},{"id":"d","texte":"D’accéder à la justice quand on a peu de moyens"}],"multiple":false},{"enonce":"Que signifie le « double degré de juridiction » ?","aide":"Le mot « appel » en est la clé.","type":"choix","options":[{"id":"a","texte":"Deux juges dans la salle"},{"id":"b","texte":"Le droit d’être jugé deux fois pour la même chose"},{"id":"c","texte":"Une double peine"},{"id":"d","texte":"Le droit de faire appel d’une décision"}],"multiple":false}]}$ex$::jsonb,
