   $ex${"titre":"Cette photo est-elle vraie ?","competence":"argumenter","situation":"Rayan veut poster une photo qui l’a mis très en colère. Ana le freine. Le dialogue est écrit pour l’exercice. Un tableau rappelle les questions à se poser.","documents":[{"id":"bulles","type":"dialogue","modele":"bulles","titre":"Avant de poster","participants":[{"nom":"Rayan","emoji":"👦","cote":"gauche"},{"nom":"Ana","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Rayan","texte":"Regarde cette photo : une manifestation violente en ville hier ! Elle a été partagée 3 000 fois. Je la poste."},{"qui":"Ana","texte":"Attends : qui l’a publiée, et quand ? Une vraie photo peut avoir dix ans."},{"qui":"Rayan","texte":"Elle m’a mis en colère, donc ça doit être vrai."},{"qui":"Ana","texte":"C’est justement l’effet recherché."}],"source":"Dialogue écrit pour l’exercice."},{"id":"questions","type":"tableau","titre":"Les cinq questions","colonnes":["La question","Ce qu’elle vérifie"],"lignes":[["Qui ?","Le site est-il identifiable ?"],["Quand ?","La photo est-elle récente ?"],["D’où ?","Remonte-t-on à une source première ?"],["Pourquoi ?","Qui a intérêt à ce que j’y croie ?"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui montre l’émotion que cherche à provoquer une infox.","aide":"Rayan l’éprouve devant la photo.","type":"zone","document":"bulles","multiple":false},{"enonce":"Un grand nombre de partages est-il un gage de fiabilité ?","aide":"Rayan s’en sert pour se convaincre.","type":"choix","options":[{"id":"a","texte":"Oui : plus c’est partagé, plus c’est vrai"},{"id":"b","texte":"Non : une infox peut être partagée des milliers de fois"},{"id":"c","texte":"Oui, si l’auteur est connu"},{"id":"d","texte":"Oui, au-delà de 1 000 partages"}],"multiple":false},{"enonce":"Quel outil permet de vérifier d’où vient une photo et depuis quand elle circule ?","aide":"Il compare l’image à d’autres déjà publiées.","type":"choix","options":[{"id":"a","texte":"Un logiciel de retouche"},{"id":"b","texte":"Un filtre de photo"},{"id":"c","texte":"Le nombre de « j’aime »"},{"id":"d","texte":"La recherche d’image inversée"}],"multiple":false},{"enonce":"Quel est le premier réflexe utile face à une infox ?","aide":"Même de bonne foi, partager, c’est diffuser.","type":"choix","options":[{"id":"a","texte":"L’imprimer"},{"id":"b","texte":"La partager avec un commentaire"},{"id":"c","texte":"Ne pas la relayer"},{"id":"d","texte":"La poster pour la démentir"}],"multiple":false}]}$ex$::jsonb,
