e":"C’est un nom suivi d’un adjectif, à la deuxième ligne.","type":"zone","document":"article","multiple":true},{"enonce":"Quelle maladie l’immunité collective et la vaccination ont-elles permis d’éradiquer en 1980 ?","aide":"C’est une maladie dont le virus ne circule plus nulle part.","type":"choix","options":[{"id":"a","texte":"L’angine"},{"id":"b","texte":"La variole"},{"id":"c","texte":"La grippe"},{"id":"d","texte":"Le rhume"}],"multiple":false}]}$ex$::jsonb,
